select n.nspname||'.'||c.relname||'.'||a.attname name,jsonb_agg(jsonb_build_object('grantee',case when acl.grantee=c.relowner then '$owner' when acl.grantee=0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(acl.grantee)::text end,'privilege',acl.privilege_type,'grantable',acl.is_grantable) order by case when acl.grantee=c.relowner then '$owner' when acl.grantee=0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(acl.grantee)::text end,acl.privilege_type) acl from pg_catalog.pg_attribute a join pg_catalog.pg_class c on c.oid=a.attrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace cross join lateral pg_catalog.aclexplode(a.attacl) acl where n.nspname in ('public','private') and a.attacl is not null group by n.nspname,c.relname,a.attname order by 1;
